import{_ as e,o as i,c as n,a2 as o}from"./chunks/framework.CgxQ0r6v.js";const m=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 3","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_III/documentacion/III-IX/Lectura_Catedra_Evaluacion_3.md","filePath":"materias/Proyecto_Sociotecnologico_III/documentacion/III-IX/Lectura_Catedra_Evaluacion_3.md"}'),s={name:"materias/Proyecto_Sociotecnologico_III/documentacion/III-IX/Lectura_Catedra_Evaluacion_3.md"};function t(r,a,l,c,d,u){return i(),n("div",null,[...a[0]||(a[0]=[o(`<h1 id="manual-de-estudio-profundo-evaluacion-3" tabindex="-1">Manual de Estudio Profundo: Evaluación 3 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-3" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 3&quot;">​</a></h1><h2 id="materia-proyecto-sociotecnologico-iii-trayecto-iii-trimestre-ix" tabindex="-1">Materia: Proyecto Sociotecnológico III (Trayecto III - Trimestre IX) <a class="header-anchor" href="#materia-proyecto-sociotecnologico-iii-trayecto-iii-trimestre-ix" aria-label="Permalink to &quot;Materia: Proyecto Sociotecnológico III (Trayecto III - Trimestre IX)&quot;">​</a></h2><h3 id="eje-tematico-elaboracion-de-manuales-tecnicos-y-transferencia-tecnologica" tabindex="-1">Eje Temático: Elaboración de Manuales Técnicos y Transferencia Tecnológica <a class="header-anchor" href="#eje-tematico-elaboracion-de-manuales-tecnicos-y-transferencia-tecnologica" aria-label="Permalink to &quot;Eje Temático: Elaboración de Manuales Técnicos y Transferencia Tecnológica&quot;">​</a></h3><hr><h2 id="🧭-introduccion-la-memoria-institucional-del-proyecto" tabindex="-1">🧭 Introducción: La Memoria Institucional del Proyecto <a class="header-anchor" href="#🧭-introduccion-la-memoria-institucional-del-proyecto" aria-label="Permalink to &quot;🧭 Introducción: La Memoria Institucional del Proyecto&quot;">​</a></h2><p>Un sistema de información desarrollado por la universidad no puede depender permanentemente de los estudiantes que lo crearon. Para que una solución sociotecnológica sea <strong>sostenible en el tiempo</strong>, debe contar con una documentación técnica rigurosa y un proceso formal de <strong>transferencia tecnológica</strong>.</p><p>En este manual se detallan los estándares para redactar los manuales de usuario y de administración del sistema en el Trayecto III, garantizando que el personal de la institución sea plenamente autónomo en su uso y mantenimiento.</p><hr><h2 id="👤-capitulo-i-el-manual-de-usuario-institucional" tabindex="-1">👤 CAPÍTULO I: El Manual de Usuario Institucional <a class="header-anchor" href="#👤-capitulo-i-el-manual-de-usuario-institucional" aria-label="Permalink to &quot;👤 CAPÍTULO I: El Manual de Usuario Institucional&quot;">​</a></h2><p>El Manual de Usuario debe estar orientado a los distintos perfiles de operadores que interactúan con el sistema:</p><h3 id="_1-1-estructura-del-manual-de-usuario" tabindex="-1">1.1 Estructura del Manual de Usuario <a class="header-anchor" href="#_1-1-estructura-del-manual-de-usuario" aria-label="Permalink to &quot;1.1 Estructura del Manual de Usuario&quot;">​</a></h3><ol><li><strong>Introducción y Alcance del Software:</strong> Objetivos del sistema en la institución.</li><li><strong>Requisitos de la Estación de Trabajo:</strong> Navegadores recomendados, resolución de pantalla y periféricos.</li><li><strong>Control de Acceso y Gestión de Perfil:</strong><ul><li>Inicio de sesión seguro, cambio de contraseña y recuperación de credenciales.</li></ul></li><li><strong>Módulos Transaccionales Paso a Paso:</strong><ul><li>Formularios de entrada con explicaciones campo por campo.</li><li>Capturas de pantalla reales anotadas con llamadas visuales (recuadros, flechas).</li><li>Significado de los botones de acción (Guardar, Editar, Desactivar, Imprimir).</li></ul></li><li><strong>Generación y Exportación de Reportes:</strong><ul><li>Cómo aplicar filtros de fecha o categoría y cómo descargar reportes en PDF o CSV.</li></ul></li><li><strong>Resolución de Problemas Comunes (FAQ):</strong> Qué hacer ante mensajes de advertencia frecuentes.</li></ol><hr><h2 id="⚙️-capitulo-ii-el-manual-del-sistema-y-de-administracion-tecnica" tabindex="-1">⚙️ CAPÍTULO II: El Manual del Sistema y de Administración Técnica <a class="header-anchor" href="#⚙️-capitulo-ii-el-manual-del-sistema-y-de-administracion-tecnica" aria-label="Permalink to &quot;⚙️ CAPÍTULO II: El Manual del Sistema y de Administración Técnica&quot;">​</a></h2><p>Dirigido a ingenieros en informática, administradores de red o técnicos de soporte institucional:</p><h3 id="_2-1-componentes-del-manual-del-sistema" tabindex="-1">2.1 Componentes del Manual del Sistema <a class="header-anchor" href="#_2-1-componentes-del-manual-del-sistema" aria-label="Permalink to &quot;2.1 Componentes del Manual del Sistema&quot;">​</a></h3><ol><li><strong>Ficha Técnica y Arquitectura:</strong> Diagrama de despliegue, capas arquitectónicas (MVC / APIs) y stack tecnológico libre.</li><li><strong>Guía de Instalación y Reinstalación de Emergencia:</strong><ul><li>Procedimiento de aprovisionamiento del servidor desde cero en Linux.</li><li>Clonación del repositorio, configuración de variables de entorno y permisos de archivos.</li></ul></li><li><strong>Estructura del Código Fuente y Diccionario de Datos:</strong><ul><li>Árbol de carpetas del proyecto y descripción de clases y modelos.</li><li>Tablas de base de datos, tipos de datos, claves primarias, foráneas e índices.</li></ul></li><li><strong>Políticas de Respaldo y Restauración de Base de Datos:</strong><ul><li>Scripts automatizados para la generación de respaldos periódicos:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Script de respaldo nocturno para PostgreSQL</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pg_dump</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -U</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bd_sistema_institucional</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /backups/respaldo_</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">date</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +%Y%m%d</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.backup</span></span></code></pre></div></li><li>Procedimiento documentado paso a paso para restaurar la base de datos ante contingencias.</li></ul></li><li><strong>Términos de Licenciamiento (GNU GPL v3):</strong> Declaración formal de software libre y libertades otorgadas a la institución.</li></ol><hr><h2 id="👥-capitulo-iii-plan-de-capacitacion-y-transferencia-tecnologica" tabindex="-1">👥 CAPÍTULO III: Plan de Capacitación y Transferencia Tecnológica <a class="header-anchor" href="#👥-capitulo-iii-plan-de-capacitacion-y-transferencia-tecnologica" aria-label="Permalink to &quot;👥 CAPÍTULO III: Plan de Capacitación y Transferencia Tecnológica&quot;">​</a></h2><p>La transferencia tecnológica no es entregar un CD; es capacitar a las personas:</p><ol><li><strong>Talleres Teórico-Prácticos:</strong> Mínimo 3 jornadas formativas cubriendo: <ul><li>Sesión 1: Filosofía del sistema y navegación básica.</li><li>Sesión 2: Práctica transaccional con casos reales.</li><li>Sesión 3: Manejo de reportes y administración técnica básica.</li></ul></li><li><strong>Evaluación de Aprendizaje:</strong> Aplicación de una prueba práctica simple a los operadores para verificar que dominan el registro y la consulta.</li><li><strong>Actas de Asistencia y Acreditación:</strong> Registros firmados que acreditan formalmente la capacitación recibida por los funcionarios comunitarios.</li></ol><hr><h2 id="📝-conclusiones-y-entregables-de-la-evaluacion-3" tabindex="-1">📝 Conclusiones y Entregables de la Evaluación 3 <a class="header-anchor" href="#📝-conclusiones-y-entregables-de-la-evaluacion-3" aria-label="Permalink to &quot;📝 Conclusiones y Entregables de la Evaluación 3&quot;">​</a></h2><p>Para la Evaluación 3 del Trimestre IX:</p><ol><li><strong>Manual de Usuario Completo:</strong> Ilustrado y encuadernado/digital en PDF.</li><li><strong>Manual del Sistema y de Administración:</strong> Con especificaciones técnicas, diagramas y scripts de respaldo.</li><li><strong>Registro de Talleres de Capacitación:</strong> Con listas de firmas y fotografías que evidencien la transferencia tecnológica.</li></ol>`,25)])])}const h=e(s,[["render",t]]);export{m as __pageData,h as default};
